import {Chess} from './vendor/chess.js';
import {Engine,classify,terminal,TYPES} from './analysis.js';
import {scoreText} from './explanations.js';
import {LEVELS,pieceNames,hintsFor,lessonFor,undoTurn,gameOutcome} from './coach-core.js';
import {getSettings,avatarSVG,escapeHTML as esc,playSound} from './settings.js';
import {animateBoard} from './motion.js';
const $=id=>document.getElementById(id),engine=new Engine(s=>$('coachEngine').textContent=s);
let chess=new Chess(),human='w',level=1,flipped=false,selected=null,phase='setup',locked=false,result=null,steps=[],step=0,hint=0,token=0,lastErrorTask=null,active=false;
const quality=()=>getSettings().quality;
function message(text){$('trainingMessage').hidden=!text;$('trainingMessage').textContent=text}
function refreshAvatar(){const s=getSettings();['setupAvatar','opponentAvatar','dialogueAvatar'].forEach(id=>$(id).innerHTML=avatarSVG(s));['setupName','opponentName','dialogueName'].forEach(id=>$(id).textContent=s.coachName)}
refreshAvatar();window.addEventListener('ply-settings',()=>{refreshAvatar();if(active){renderBoard();renderDialogue()}});
function save(){try{localStorage.setItem('plystreak-training',JSON.stringify({version:1,pgn:chess.pgn(),human,level}));$('saveStatus').textContent='Entra ed esci quando vuoi: allenamento salvato sul dispositivo.'}catch{$('saveStatus').textContent='Salvataggio non disponibile: esporta il PGN per conservare la partita.'}}
function setBusy(value){locked=value;renderBoard();['undoTraining','newLesson','continueLesson','retryMove','askHint','retryEngine','reviewTraining','exportTraining'].forEach(id=>$(id).disabled=value);document.querySelectorAll('[data-question]').forEach(b=>b.disabled=value)}
function renderBoard(){const legal=selected?chess.moves({square:selected,verbose:true}).map(m=>m.to):[],last=chess.history({verbose:true}).at(-1);let html='';for(let row=0;row<8;row++)for(let col=0;col<8;col++){const f=flipped?7-col:col,r=flipped?row:7-row,sq='abcdefgh'[f]+(r+1),p=chess.get(sq);html+=`<button class="square ${(f+r)%2===0?'dark':''} ${selected===sq?'selected':''} ${legal.includes(sq)?'legal':''} ${last&&(last.from===sq||last.to===sq)?'last':''} ${p?.type==='k'&&p.color===chess.turn()&&chess.isCheck()?'in-check':''}" data-sq="${sq}" aria-label="${sq}${p?' '+(p.color==='w'?'Bianco ':'Nero ')+pieceNames[p.type]:''}" ${locked||phase!=='user'?'disabled':''}>${p?`<img src="pieces/${p.color}${p.type.toUpperCase()}.png" alt="" draggable="false">`:''}${col===0?`<span class="coord rank">${r+1}</span>`:''}${row===7?`<span class="coord">${'abcdefgh'[f]}</span>`:''}</button>`}$('trainingBoard').innerHTML=html;animateBoard($('trainingBoard'),chess.fen(),flipped);$('humanBadge').textContent=human==='w'?'B':'N';$('turnStatus').textContent=gameOutcome(chess)||(locked?'Il coach sta ragionando…':phase==='user'?'Tocca un tuo pezzo, poi la casa di destinazione.':'Leggi il commento del coach, poi continua.');$('trainingMoves').textContent=chess.history().map((m,i)=>(i%2===0?`${i/2+1}. `:'')+m).join(' ')||'La tua prima mossa ti aspetta.';$('undoTraining').disabled=locked||!chess.history().length;$('reviewTraining').disabled=locked||!chess.history().length;$('opponentLevel').textContent=LEVELS[level].name+' · '+(human==='w'?'Nero':'Bianco')}
function renderDialogue(){const guided=getSettings().coachDetail==='guided';$('hintControls').hidden=phase!=='user';$('lessonControls').hidden=!steps.length||!guided||!['feedback','aiFeedback'].includes(phase);$('continueLesson').hidden=!['feedback','aiFeedback'].includes(phase);$('retryMove').hidden=phase!=='feedback';$('retryEngine').hidden=phase!=='error';$('phaseBadge').textContent={setup:'Preparazione',thinking:'Analisi',user:'Il tuo turno',feedback:'La tua mossa',aiFeedback:'La mia risposta',ended:'Fine partita',error:'In pausa'}[phase];
if(['feedback','aiFeedback'].includes(phase)){$('coachContent').innerHTML=(guided?[steps[step]]:steps).map(s=>`<section class="lesson-step"><h3>${esc(s.title)}</h3><p>${esc(s.text)}</p></section>`).join('');$('stepCount').textContent=`${step+1} / ${steps.length}`;$('stepBack').disabled=step===0;$('stepNext').disabled=step===steps.length-1;$('continueLesson').textContent=gameOutcome(chess)?'Concludi l’allenamento →':phase==='feedback'?'Fai giocare il coach →':'Tocca a me →'}
else if(phase==='user'){$('coachContent').innerHTML=`<h3>${chess.isCheck()?'Prima metti al sicuro il re.':'Prenditi un momento per osservare.'}</h3><p>${esc(hintsFor(chess,result)[0])}</p><p>Qual è il tuo piano? Scegli una mossa sulla scacchiera. Se ti serve una mano, chiedimi un indizio.</p>`;$('hintText').textContent='';hint=0;$('askHint').textContent='Dammi un indizio'}
else if(phase==='thinking')$('coachContent').innerHTML='<h3>Guardiamo le possibilità…</h3><p>Sto confrontando le mosse e la risposta più forte dell’avversario.</p>';
else if(phase==='ended')$('coachContent').innerHTML=`<h3>${esc(gameOutcome(chess)||'Allenamento concluso.')}</h3><p>Ogni partita lascia qualcosa da imparare. Apri “Rivedi partita” per analizzare tutte le mosse, oppure esporta il PGN.</p>`;
}
async function analyze(){return terminal(chess)||await engine.evaluate(chess.fen(),quality())}
async function run(task){const id=++token;lastErrorTask=task;setBusy(true);message('');try{await task(id)}catch(e){if(id===token){phase='error';$('coachContent').innerHTML='<h3>Il motore si è fermato.</h3><p>La partita è conservata. Riprova oppure esporta il PGN.</p>';message(e.message)}}finally{if(id===token){setBusy(false);renderBoard();renderDialogue();save()}}}
async function prepareTurn(){if(gameOutcome(chess)){phase='ended';renderDialogue();return}phase='thinking';renderDialogue();result=await analyze();if(chess.turn()!==human){await botTurn();return}phase='user';steps=[];step=0}
async function botTurn(){phase='thinking';renderDialogue();const before=result||await analyze();const selection=await engine.evaluate(chess.fen(),'quick','',{skill:LEVELS[level].skill,limits:LEVELS[level].limits});const u=selection.best;if(!u||u==='(none)')throw Error('Nessuna mossa ricevuta: riprova il motore.');const m=chess.move({from:u.slice(0,2),to:u.slice(2,4),promotion:u[4]||'q'});selected=null;playSound();renderBoard();save();result=await analyze();const grade=classify({before,after:result,side:m.color==='w'?1:-1,uci:u,book:false});steps=lessonFor(m,before,result,grade);steps[0].title='1 · La risposta del coach';steps[0].text='Ho giocato '+m.san+'. '+steps[0].text;steps[1].text=(level<4?'Al livello scelto posso giocare mosse imperfette. ':'')+steps[1].text;phase='aiFeedback';step=0}
async function humanMove(from,to,promotion){if(locked||phase!=='user'||chess.turn()!==human)return;const candidates=chess.moves({square:from,verbose:true}).filter(m=>m.to===to);if(!candidates.length)return;if(candidates.some(m=>m.promotion)&&!promotion){promotion=await choosePromotion();if(!promotion)return}await run(async()=>{const before=result||await analyze();const m=chess.move({from,to,promotion:promotion||'q'});selected=null;phase='thinking';renderBoard();renderDialogue();playSound();save();result=await analyze();const grade=classify({before,after:result,side:human==='w'?1:-1,uci:m.from+m.to+(m.promotion||''),book:false});steps=lessonFor(m,before,result,grade);steps[1].title='2 · '+TYPES[grade.type].label;phase='feedback';step=0})}
function choosePromotion(){return new Promise(resolve=>{const d=$('trainingPromotion');$('trainingPromotionOptions').innerHTML=['q','r','b','n'].map(p=>`<button data-promotion="${p}" aria-label="${pieceNames[p]}"><img alt="${pieceNames[p]}" src="pieces/${human}${p.toUpperCase()}.png"></button>`).join('');const done=p=>{d.close();resolve(p)};$('trainingPromotionOptions').onclick=e=>{const b=e.target.closest('[data-promotion]');if(b)done(b.dataset.promotion)};$('cancelTrainingPromotion').onclick=()=>done(null);d.oncancel=e=>{e.preventDefault();done(null)};d.showModal()})}
function activate(){active=true;flipped=human==='b';selected=null;result=null;steps=[];step=0;phase='thinking';$('setup').hidden=true;$('training').hidden=false;$('questionAnswer').textContent='Seleziona una domanda per ragionare sulla posizione attuale.';save();renderBoard();renderDialogue();run(prepareTurn)}
$('difficulty').onchange=()=>$('difficultyDescription').textContent=LEVELS[Number($('difficulty').value)].description;$('difficulty').onchange();
$('startLesson').onclick=()=>{chess=new Chess();human=$('humanSide').value;if(human==='random')human=Math.random()<.5?'w':'b';level=Number($('difficulty').value);chess.setHeader('Event','Plystreak · Allenamento');chess.setHeader('White',human==='w'?'Tu':getSettings().coachName);chess.setHeader('Black',human==='b'?'Tu':getSettings().coachName);activate()};
function resume(){try{const s=JSON.parse(localStorage.getItem('plystreak-training'));if(!s||s.version!==1||!['w','b'].includes(s.human)||!Number.isInteger(s.level)||!LEVELS[s.level])throw Error('Salvataggio non valido.');chess=new Chess();if(s.pgn)chess.loadPgn(s.pgn);human=s.human;level=s.level;activate()}catch(e){message('Impossibile riprendere: '+e.message)}}
try{$('resumeLesson').hidden=!localStorage.getItem('plystreak-training')}catch{}
$('resumeLesson').onclick=resume;$('newLesson').onclick=()=>{if(locked)return;active=false;phase='setup';$('training').hidden=true;$('setup').hidden=false;$('resumeLesson').hidden=false;message('')};
$('trainingBoard').onclick=e=>{const b=e.target.closest('[data-sq]');if(!b||locked||phase!=='user')return;const sq=b.dataset.sq,p=chess.get(sq);if(selected&&chess.moves({square:selected,verbose:true}).some(m=>m.to===sq)){humanMove(selected,sq);return}selected=p?.color===human?sq:null;renderBoard()};
$('continueLesson').onclick=()=>{if(locked)return;if(gameOutcome(chess)){phase='ended';steps=[];renderDialogue();renderBoard();return}if(phase==='feedback')run(botTurn);else if(phase==='aiFeedback'){phase='user';steps=[];selected=null;renderBoard();renderDialogue()}};
async function undo(){if(locked)return;undoTurn(chess,human);selected=null;result=null;steps=[];await run(prepareTurn)}
$('undoTraining').onclick=undo;$('retryMove').onclick=undo;$('retryEngine').onclick=()=>{result=null;run(prepareTurn)};
$('flipTraining').onclick=()=>{flipped=!flipped;renderBoard()};$('stepNext').onclick=()=>{step=Math.min(steps.length-1,step+1);renderDialogue()};$('stepBack').onclick=()=>{step=Math.max(0,step-1);renderDialogue()};
$('askHint').onclick=()=>{if(phase!=='user'||locked)return;const hints=hintsFor(chess,result);$('hintText').textContent=hints[Math.min(hint,2)];hint=Math.min(3,hint+1);$('askHint').textContent=hint<3?'Un indizio in più':'Rileggi il suggerimento';if(hint===3){const u=result?.lines?.[0]?.pv[0];if(u){$('trainingBoard').querySelector(`[data-sq="${u.slice(0,2)}"]`)?.classList.add('hint-square');$('trainingBoard').querySelector(`[data-sq="${u.slice(2,4)}"]`)?.classList.add('hint-square')}}};
document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>{if(locked)return;const c=chess,side=c.turn(),hints=hintsFor(c,result);if(b.dataset.question==='best')$('questionAnswer').textContent=hints[2];else if(b.dataset.question==='plan')$('questionAnswer').textContent=hints[0];else{const targets=c.board().flat().filter(p=>p&&p.color===side&&c.isAttacked(p.square,side==='w'?'b':'w'));$('questionAnswer').textContent=targets.length?`Per il ${side==='w'?'Bianco':'Nero'}, questi pezzi sono attaccati geometricamente: ${targets.map(p=>pieceNames[p.type]+' in '+p.square).join(', ')}. Un attacco non implica una perdita: controlla difensori, inchiodature e catture legali.`:'Non risultano pezzi del lato al tratto sotto attacco diretto. Controlla comunque scacchi, catture e minacce dopo la tua prossima mossa.'}});
$('exportTraining').onclick=async()=>{const outcome=gameOutcome(chess);chess.setHeader('Result',chess.isCheckmate()?(chess.turn()==='w'?'0-1':'1-0'):outcome?'1/2-1/2':'*');const text=chess.pgn();const file=new File([text],'plystreak-allenamento.pgn',{type:'text/plain'});if(window.Capacitor?.isNativePlatform()){if(navigator.canShare?.({files:[file]})){try{await navigator.share({files:[file]})}catch{}return}const d=document.createElement('dialog'),a=document.createElement('textarea'),b=document.createElement('button');a.value=text;a.readOnly=true;b.textContent='Chiudi';b.onclick=()=>d.remove();d.append('Seleziona e copia il PGN.',a,b);document.body.append(d);d.showModal();return}const url=URL.createObjectURL(file),a=document.createElement('a');a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)};
$('reviewTraining').onclick=()=>{if(locked||!chess.history().length)return;try{localStorage.setItem('plystreak-review-import',chess.pgn());location.href='index.html?training=1'}catch{message('Memoria non disponibile. Esporta il PGN e importalo nella revisione.')}};
